export const FONT_FACE_CSS = `
@font-face{font-family:'Monument';src:url(data:font/otf;base64,${MONUMENT_REGULAR}) format('opentype');font-weight:400;font-style:normal;}
@font-face{font-family:'Monument';src:url(data:font/otf;base64,${MONUMENT_BLACK}) format('opentype');font-weight:900;font-style:normal;}
@font-face{font-family:'Funnel';src:url(data:font/ttf;base64,${FUNNEL}) format('truetype');font-weight:300 800;font-style:normal;}
`;
